1	import { Effect } from "effect";
2	import type { StoredLibraryCard } from "@inkling/contracts";
3	import { IMAGE_MODEL, TEXT_MODEL } from "../embedding-contract.ts";
4	import { selectCards, type StorageContext } from "./context.ts";
5	import { invalidInput } from "./errors.ts";
6	import {
7	  cardColumns,
8	  cardFromRow,
9	  cardItem,
10	  clampLimit,
11	  type ItemRow,
12	  itemFromRow,
13	  qualifiedCardColumns,
14	} from "./shared.ts";
15	
16	const semanticMatchFloor = 0.55;
17	
18	type EmbeddingRow = {
19	  item_id: string;
20	  updated_at: number;
21	  embedding_dimension: number;
22	  embedding_vector: Uint8Array;
23	};
24	
25	export type QueryVector = ArrayLike<number> | null | undefined;
26	
27	export function escapeFtsQuery(query: string) {
28	  return query
29	    .split(/\s+/)
30	    .filter(Boolean)
31	    .map((token) => `"${token.replaceAll('"', "")}"`)
32	    .filter((token) => token !== '""')
33	    .join(" ");
34	}
35	
36	function decodeFloatVector(blob: Uint8Array | null, dimension: number) {
37	  if (!blob || blob.byteLength !== dimension * 4) return null;
38	  // Vectors are stored little-endian, which every platform we ship reads natively.
39	  // A Float32Array view needs a 4-byte-aligned offset, so copy when the driver gives none.
40	  const aligned = blob.byteOffset % 4 === 0 ? blob : new Uint8Array(blob);
41	  return new Float32Array(aligned.buffer, aligned.byteOffset, dimension);
42	}
43	
44	function dotProduct(left: ArrayLike<number>, right: ArrayLike<number>) {
45	  if (left.length !== right.length) return Number.NEGATIVE_INFINITY;
46	  let score = 0;
47	  for (let index = 0; index < left.length; index += 1) score += left[index] * right[index];
48	  return score;
49	}
50	
51	export function sqlLikePattern(value: string) {
52	  return `%${value.replace(/[\\%_]/g, "\\$&")}%`;
53	}
54	
55	export function makeSearch(ctx: StorageContext) {
56	  const { sql } = ctx;
57	
58	  const likeClause = (pattern: string, prefix = "") => {
59	    const column = (name: string) =>
60	      sql`${sql.literal(`${prefix}${name}`)} COLLATE NOCASE LIKE ${pattern} ESCAPE char(92)`;
61	    return sql`(${sql.or(["title", "description", "body", "source_label", "ocr_text", "metadata"].map(column))})`;
62	  };
63	
64	  const cardsById = Effect.fnUntraced(function* (orderedIds: ReadonlyArray<string>) {
65	    if (!orderedIds.length) return [] as StoredLibraryCard[];
66	    const rows = yield* sql<ItemRow>`SELECT ${sql.literal(qualifiedCardColumns)}
67	      FROM items i WHERE i.id IN (SELECT value FROM json_each(${JSON.stringify(orderedIds)}))`;
68	    const byId = new Map(rows.map((row) => [row.id, cardFromRow(row)]));
69	    return orderedIds.flatMap((id) => {
70	      const card = byId.get(id);
71	      return card ? [card] : [];
72	    });
73	  });
74	
75	  const storeEmbedding = Effect.fnUntraced(function* (
76	    itemId: string,
77	    kind: string,
78	    model: string,
79	    bytes: Uint8Array,
80	    dimension: number,
81	  ) {
82	    if (kind !== "text" && kind !== "image") {
83	      return yield* invalidInput("embedding kind must be text or image");
84	    }
85	    const vector = Buffer.from(bytes);
86	    if (!Number.isInteger(dimension) || dimension < 1 || vector.length !== dimension * 4) {
87	      return yield* invalidInput("embedding vector dimension does not match its bytes");
88	    }
89	    yield* sql`INSERT INTO item_embeddings (item_id, kind, model, dimension, vector, created_at)
90	      VALUES (${itemId}, ${kind}, ${String(model)}, ${dimension}, ${vector}, ${Date.now()})
91	      ON CONFLICT(item_id, kind) DO UPDATE SET model = excluded.model,
92	      dimension = excluded.dimension, vector = excluded.vector, created_at = excluded.created_at`;
93	  });
94	
95	  const searchItems = Effect.fnUntraced(function* (
96	    query: unknown,
97	    limit: unknown = 100,
98	    queryVector: QueryVector = null,
99	  ) {
100	    const search = String(query ?? "").trim();
101	    const cap = clampLimit(limit, 100, 200);
102	    if (!search) return yield* selectCards(ctx, sql`archived = 0`, cap);
103	    let rows: ReadonlyArray<ItemRow> = [];
104	    if (ctx.fts5Enabled) {
105	      const match = escapeFtsQuery(search);
106	      if (match) {
107	        rows = yield* sql<ItemRow>`SELECT ${sql.literal(qualifiedCardColumns)}
108	          FROM items_fts f JOIN items i ON i.id = f.item_id
109	          WHERE i.archived = 0 AND items_fts MATCH ${match}
110	          ORDER BY i.updated_at DESC, i.created_at DESC LIMIT ${cap}`;
111	      }
112	    } else {
113	      rows = yield* sql<ItemRow>`SELECT ${sql.literal(cardColumns)} FROM items
114	        WHERE archived = 0 AND ${likeClause(sqlLikePattern(search))}
115	        ORDER BY updated_at DESC, created_at DESC LIMIT ${cap}`;
116	    }
117	    const lexicalItems = rows.map(itemFromRow);
118	    if (!queryVector?.length) return lexicalItems.map(cardItem);
119	
120	    const ranked = new Map(
121	      lexicalItems.map((item) => [item.id, { score: 2, updatedAt: item.updatedAt }]),
122	    );
123	    const candidates = yield* sql<EmbeddingRow>`SELECT e.item_id, i.updated_at,
124	      e.dimension AS embedding_dimension, e.vector AS embedding_vector
125	      FROM item_embeddings e JOIN items i ON i.id = e.item_id
126	      WHERE i.archived = 0 AND ((e.kind = 'text' AND e.model = ${TEXT_MODEL})
127	        OR (e.kind = 'image' AND e.model = ${IMAGE_MODEL}))`;
128	    for (const row of candidates) {
129	      const vector = decodeFloatVector(row.embedding_vector, row.embedding_dimension);
130	      if (!vector || vector.length !== queryVector.length) continue;
131	      const similarity = dotProduct(queryVector, vector);
132	      const current = ranked.get(row.item_id);
133	      if (similarity < semanticMatchFloor && !current) continue;
134	      const score = current ? 2 + Math.max(similarity, 0) : similarity;
135	      if (current) current.score = Math.max(current.score, score);
136	      else ranked.set(row.item_id, { score, updatedAt: row.updated_at });
137	    }
138	
139	    const winners = [...ranked.entries()]
140	      .sort(
141	        (left, right) => right[1].score - left[1].score || right[1].updatedAt - left[1].updatedAt,
142	      )
143	      .slice(0, cap)
144	      .map(([id]) => id);
145	    return yield* cardsById(winners);
146	  });
147	
148	  const searchSimilar = Effect.fnUntraced(function* (
149	    itemId: string,
150	    kind: "image" | "text",
151	    limit: unknown = 12,
152	  ) {
153	    const model = kind === "image" ? IMAGE_MODEL : TEXT_MODEL;
154	    const [source] = yield* sql<{ dimension: number; vector: Uint8Array }>`SELECT dimension, vector
155	      FROM item_embeddings WHERE item_id = ${itemId} AND kind = ${kind} AND model = ${model}`;
156	    if (!source) return [] as StoredLibraryCard[];
157	    const sourceVector = decodeFloatVector(source.vector, source.dimension);
158	    if (!sourceVector)
159	      return yield* invalidInput(`stored ${kind} embedding dimension does not match its vector`);
160	    const kinds =
161	      kind === "image" ? sql`i.kind = 'image'` : sql`i.kind IN ('article', 'url', 'note', 'quote')`;
162	    const candidates = yield* sql<EmbeddingRow>`SELECT e.item_id, i.updated_at,
163	      e.dimension AS embedding_dimension, e.vector AS embedding_vector
164	      FROM item_embeddings e JOIN items i ON i.id = e.item_id
165	      WHERE i.archived = 0 AND i.id != ${itemId} AND ${kinds}
166	      AND e.kind = ${kind} AND e.model = ${model}`;
167	    const winners = candidates
168	      .flatMap((row) => {
169	        const vector = decodeFloatVector(row.embedding_vector, row.embedding_dimension);
170	        return vector && vector.length === sourceVector.length
171	          ? [{ id: row.item_id, score: dotProduct(sourceVector, vector) }]
172	          : [];
173	      })
174	      .sort((left, right) => right.score - left.score)
175	      .slice(0, clampLimit(limit, 12, 50))
176	      .map(({ id }) => id);
177	    return yield* cardsById(winners);
178	  });
179	
180	  return { storeEmbedding, searchItems, searchSimilar, likeClause };
181	}
